// Exercise boost::compute::system::default_device().
// Requirements enforced: must succeed if a default device is discoverable; otherwise we bail on the thrown exception.
try {
    boost::compute::device dev = boost::compute::system::default_device();
    // Touch a trivial property to exercise returned object; do not persist it.
    (void)dev.name();
} catch(...) {
    // If no device is available or selection rules fail, the API throws; treat as expected error.
    FUZZ_BAIL();
}
// Validation: Invoked API under try/catch; no persistent objects to return; exceptions correctly mapped to FUZZ_BAIL().

// Exercise boost::compute::system::find_device(name) with both matching and non-matching names.
std::string random_name = FUZZ_PARAM_STR();
unsigned int choice = *FUZZ_PARAM(unsigned int);
try {
    // 50/50: either use an existing device name (if any), or a random name to trigger the not-found path.
    if ((choice & 1u) == 0) {
        std::vector<boost::compute::device> all = boost::compute::system::devices();
        if (!all.empty()) {
            const boost::compute::device &pick = all[(*FUZZ_PARAM(unsigned int)) % all.size()];
            boost::compute::device found = boost::compute::system::find_device(pick.name());
            (void)found.name();
        } else {
            // No devices available: any lookup will throw; run with random_name to cover throw path.
            (void)boost::compute::system::find_device(random_name);
        }
    } else {
        // Intentionally likely to fail, to cover exception path.
        (void)boost::compute::system::find_device(random_name);
    }
} catch(...) {
    // Not-found or environment-driven selection failure is an expected outcome.
    FUZZ_BAIL();
}
// Validation: When devices exist, we attempt a guaranteed-match path; otherwise exercise throw path. All exceptions mapped to FUZZ_BAIL(); no persistent outputs.

// Exercise enumeration of devices and assert it matches device_count().
try {
    std::vector<boost::compute::device> devs = boost::compute::system::devices();
    // Touch device properties to increase coverage.
    for (size_t i = 0; i < devs.size() && i < 8; ++i) {
        (void)devs[i].name();
    }
    size_t count = boost::compute::system::device_count();
    // Property: device_count() must equal devices().size() per implementation.
    FUZZ_ASSERT(count == devs.size(), "device_count() must equal devices().size()");
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Enumerates devices and asserts count consistency; any unexpected exception results in FUZZ_BAIL().

// Exercise device_count() and cross-check with devices().
try {
    size_t count = boost::compute::system::device_count();
    size_t vec_count = boost::compute::system::devices().size();
    FUZZ_ASSERT(count == vec_count, "device_count() must equal devices().size()");
    (void)count;
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Checks property equality with devices().size(); exceptions are handled via FUZZ_BAIL().

// Exercise boost::compute::system::default_context().
try {
    boost::compute::context ctx = boost::compute::system::default_context();
    // Touch the underlying handle if available through get(); ignore result.
    (void)ctx.get();
} catch(...) {
    // May throw if default_device() cannot be obtained.
    FUZZ_BAIL();
}
// Validation: Obtains default context and uses it minimally; exceptions mapped to FUZZ_BAIL().

// Exercise boost::compute::system::default_queue() without providing a user queue
// to avoid cross-call global state constraints.
try {
    boost::compute::command_queue &q = boost::compute::system::default_queue();
    // Exercise a simple operation on the queue to increase coverage.
    q.finish();
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Accesses the default queue safely with no user_queue; exceptions are handled via FUZZ_BAIL().

// Exercise system::finish() which blocks until the default queue is idle.
try {
    boost::compute::system::finish();
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Simply invokes finish(); exceptions from default_queue() or queue.finish() cause FUZZ_BAIL().

// Exercise enumeration of OpenCL platforms and assert agreement with platform_count().
try {
    std::vector<boost::compute::platform> plats = boost::compute::system::platforms();
    for (size_t i = 0; i < plats.size() && i < 8; ++i) {
        (void)plats[i].name();
    }
    size_t count = boost::compute::system::platform_count();
    FUZZ_ASSERT(count == plats.size(), "platform_count() must equal platforms().size()");
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Enumerates platforms, touches a few, and asserts count consistency; exceptions mapped to FUZZ_BAIL().

// Exercise platform_count() and cross-check with platforms().
try {
    size_t count = boost::compute::system::platform_count();
    size_t vec_count = boost::compute::system::platforms().size();
    FUZZ_ASSERT(count == vec_count, "platform_count() must equal platforms().size()");
    (void)count;
} catch(...) {
    FUZZ_BAIL();
}
// Validation: Validates count equality to platforms().size(); any exceptions lead to FUZZ_BAIL().
